create table public.partial_bottle_listings(id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.profiles(id) on delete cascade,fragrance_id uuid references public.fragrances(id),perfume_name text not null,brand_name text,days_used int check(days_used>=0),percent_left int not null check(percent_left between 1 and 100),has_box boolean not null default false,price numeric not null check(price>=0),currency text not null default 'BDT',payment_method text not null check(payment_method in('online','face-to-face','both')),location text,contact_info text not null,photos text[] not null default '{}',description text,status text not null default 'active',created_at timestamptz not null default now());
create index partial_listings_seller_idx on public.partial_bottle_listings(seller_id);
create index partial_listings_status_idx on public.partial_bottle_listings(status);
create table public.partial_listing_inquiries(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.partial_bottle_listings(id) on delete cascade,buyer_id uuid not null references public.profiles(id) on delete cascade,message text,status text not null default 'pending',created_at timestamptz not null default now());
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade,listing_id uuid references public.partial_bottle_listings(id) on delete cascade,reported_user_id uuid references public.profiles(id) on delete cascade,reason text not null,details text,status text not null default 'open',created_at timestamptz not null default now(),check(listing_id is not null or reported_user_id is not null));
